import 'package:flutter/material.dart';
import '../models/product.dart';
import '../presentation/facades/user_service.dart';
import '../core/network/api_client.dart';
import '../widgets/app_button.dart';
import '../widgets/shop_bottom_nav.dart';

class CartScreen extends StatefulWidget { const CartScreen({super.key}); @override State<CartScreen> createState() => _CartScreenState(); }
class _CartScreenState extends State<CartScreen> {
  late Future<List<Product>> future;
  @override void initState() { super.initState(); future = UserService.getCart(); }
  void refresh() => setState(() => future = UserService.getCart());
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('My Cart', style: TextStyle(fontSize: 16)), centerTitle: true), body: FutureBuilder<List<Product>>(future: future, builder: (context, snap) { if (snap.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator()); if (snap.hasError) return Center(child: Text(ApiClient.errorMessage(snap.error!))); final products = snap.data ?? []; if (products.isEmpty) return Center(child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(Icons.shopping_cart_outlined, size: 90, color: Colors.grey.shade300), const SizedBox(height: 12), const Text('Your cart is empty')])); final subtotal = products.fold<double>(0, (sum, p) => sum + p.price); const shipping = 45.0; return ListView(padding: const EdgeInsets.all(12), children: [...products.map((p) => Container(margin: const EdgeInsets.only(bottom: 10), padding: const EdgeInsets.all(10), decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(8)), child: Row(children: [Container(width: 75, height: 80, color: const Color(0xFFE7E7E7), child: p.image.isEmpty ? const Icon(Icons.shopping_bag, color: Colors.grey) : Image.network(p.image, fit: BoxFit.cover, errorBuilder: (_, _, _) => const Icon(Icons.shopping_bag))), const SizedBox(width: 10), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(p.title, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 12)), const SizedBox(height: 8), Text('EGP ${p.price.toStringAsFixed(0)}', style: const TextStyle(fontSize: 11))])), IconButton(icon: const Icon(Icons.delete_outline), onPressed: () async { try { await UserService.deleteCart(p.id); refresh(); } catch (e) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(ApiClient.errorMessage(e)))); } })]))), const SizedBox(height: 8), _line('Shipping fee', 'EGP ${shipping.toStringAsFixed(0)}'), _line('Subtotal', 'EGP ${subtotal.toStringAsFixed(0)}'), _line('Total', 'EGP ${(subtotal + shipping).toStringAsFixed(0)}'), AppButton(text: 'Checkout', onPressed: () => ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Checkout/payment endpoint is not included in the provided API.'))))]); }), bottomNavigationBar: const ShopBottomNav(selected: 1));
  Widget _line(String title, String value) => ListTile(title: Text(title, style: const TextStyle(fontSize: 12)), trailing: Text(value, style: const TextStyle(fontSize: 12)));
}